//! | `s_2` | max{d1·n2·n3·n4, n1·d2·n3·n4, n1·n2·d3·n4} | no | 6 + 34u + 80u^2 + 100u^3 + 70u^4 + 26u^5 + 4u^6 | 58u + 196u^2 + 264u^3 + 184u^4 + 70u^5 + 12u^6 |
//! | `s_3` | max{d1·n2·n3·n4, n1·d2·n3·n4, n1·n2·d3·n4, n1·n2·n3·d4} | no | 12 + 80u + 228u^2 + 360u^3 + 340u^4 + 192u^5 + 60u^6 + 8u^7 | 128u + 460u^2 + 688u^3 + 568u^4 + 280u^5 + 76u^6 + 8u^7 |
//! | `n4y` | n4 | no | 1 | u |
//! | `s_4` | max{d1·n2·n3·n4, n1·d2·n3·n4, n1·n2·d3·n4} | no | 6 + 34u + 80u^2 + 100u^3 + 70u^4 + 26u^5 + 4u^6 | 58u + 196u^2 + 264u^3 + 184u^4 + 70u^5 + 12u^6 |
//! | `s_5` | max{d1·n2·n3·n4, n1·d2·n3·n4, n1·n2·d3·n4, n1·n2·n3·d4} | no | 18 + 132u + 422u^2 + 768u^3 + 870u^4 + 628u^5 + 282u^6 + 72u^7 + 8u^8 | 204u + 770u^2 + 1260u^3 + 1212u^4 + 760u^5 + 306u^6 + 72u^7 + 8u^8 |
//! | `n4z` | n4 | no | 1 | u |
//! | `s_6` | max{d1·n2·n3·n4, n1·d2·n3·n4, n1·n2·d3·n4} | no | 6 + 34u + 80u^2 + 100u^3 + 70u^4 + 26u^5 + 4u^6 | 58u + 196u^2 + 264u^3 + 184u^4 + 70u^5 + 12u^6 |
//! | `s` | max{d1·n2·n3·n4, n1·d2·n3·n4, n1·n2·d3·n4, n1·n2·n3·d4} | no | 24 + 190u + 668u^2 + 1370u^3 + 1808u^4 + 1594u^5 + 940u^6 + 358u^7 + 80u^8 + 8u^9 | 286u + 1132u^2 + 2026u^3 + 2264u^4 + 1770u^5 + 972u^6 + 358u^7 + 80u^8 + 8u^9 |
//!
//! The filter computes the scale S at run time at least (1 − u)^3 times its exact value: 3
//! rounding(s), each product counting its own and both its operands', each `larger` the larger of
//! its operands'. It computes the bound as the constant times S, one more rounding: k = 3 + 1. The
//! constant is E · (1 + 2u)^k, rounded up to an `f64`.
//!
//! | Quantity | Value |
//! | --- | --- |
//! | Result | `s` |
//! | Unit error E | 286u + 1132u^2 + 2026u^3 + 2264u^4 + 1770u^5 + 972u^6 + 358u^7 + 80u^8 + 8u^9 |
//! | Scale S | max{d1·n2·n3·n4, n1·d2·n3·n4, n1·n2·d3·n4, n1·n2·n3·d4} |
//! | Scale at run time | `larger(larger(larger(m_d1 * m_n2 * m_n3 * m_n4, m_n1 * m_d2 * m_n3 * m_n4), m_n1 * m_n2 * m_d3 * m_n4), m_n1 * m_n2 * m_n3 * m_d4)` |
//! | Roundings k | 4 |
//! | Constant, exactly | 286u + 3420u^2 + 17946u^3 + 54792u^4 + 109306u^5 + 152412u^6 + 155478u^7 + 119136u^8 + 68664u^9 + 28992u^10 + 8480u^11 + 1536u^12 + 128u^13 |
//! | Constant as an `f64` | `0x3d21e00000000007` = 5031365208702983 · 2^-97 ≈ 3.175237850427952e-14 |
//!
//! Cost: the filter is 54 `f64` operations, after 16 rounded input(s) converted to `f64`, then 16
//! magnitudes and their maxima and the bound's 13 multiplication(s); the exact path, run only when
//! the filter cannot decide, is 54 checked integer operations.

use crate::sign::Sign;
use crate::wide::{I256, I384};

use super::{decide, larger, largest_magnitude, rounded_f64, within};

/// The filter's error constant: E · (1 + 2u)^4 with E = 286u + 1132u^2 + 2026u^3 + 2264u^4 +
/// 1770u^5 + 972u^6 + 358u^7 + 80u^8 + 8u^9, the result's unit error (header), rounded up to an
/// `f64`: 5031365208702983 · 2^-97.
const ERROR: f64 = f64::from_bits(0x3d21_e000_0000_0007);

/// `tpi_side`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero; `None` also
/// for a rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    clippy::too_many_arguments,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(
    n1x: i128,
    n1y: i128,
    n1z: i128,
    d1: i128,
    n2x: i128,
    n2y: i128,
    n2z: i128,
    d2: i128,
    n3x: i128,
    n3y: i128,
    n3z: i128,
    d3: i128,
    n4x: i128,
    n4y: i128,
    n4z: i128,
    d4: i128,
) -> Option<Sign> {
    let n2y = rounded_f64(n2y, 83)?;
    let n3z = rounded_f64(n3z, 83)?;
    let c23_x_1 = n2y * n3z;
    let n2z = rounded_f64(n2z, 83)?;
    let n3y = rounded_f64(n3y, 83)?;
    let c23_x_2 = n2z * n3y;
    let c23_x = c23_x_1 - c23_x_2;
    let n3x = rounded_f64(n3x, 83)?;
    let c23_y_1 = n2z * n3x;
    let n2x = rounded_f64(n2x, 83)?;
    let c23_y_2 = n2x * n3z;
    let c23_y = c23_y_1 - c23_y_2;
    let c23_z_1 = n2x * n3y;
    let c23_z_2 = n2y * n3x;
    let c23_z = c23_z_1 - c23_z_2;
    let n1z = rounded_f64(n1z, 83)?;
    let c31_x_1 = n3y * n1z;
    let n1y = rounded_f64(n1y, 83)?;
    let c31_x_2 = n3z * n1y;
    let c31_x = c31_x_1 - c31_x_2;
    let n1x = rounded_f64(n1x, 83)?;
    let c31_y_1 = n3z * n1x;
    let c31_y_2 = n3x * n1z;
    let c31_y = c31_y_1 - c31_y_2;
    let c31_z_1 = n3x * n1y;
    let c31_z_2 = n3y * n1x;
    let c31_z = c31_z_1 - c31_z_2;
    let c12_x_1 = n1y * n2z;
    let c12_x_2 = n1z * n2y;
    let c12_x = c12_x_1 - c12_x_2;
    let c12_y_1 = n1z * n2x;
    let c12_y_2 = n1x * n2z;
    let c12_y = c12_y_1 - c12_y_2;
    let c12_z_1 = n1x * n2y;
    let c12_z_2 = n1y * n2x;
    let c12_z = c12_z_1 - c12_z_2;
    let w_1 = n1x * c23_x;
    let w_2 = n1y * c23_y;
    let w_3 = w_1 + w_2;
    let w_4 = n1z * c23_z;
    let w = w_3 + w_4;
    let d1 = rounded_f64(d1, 125)?;
    let mx_x_1 = d1 * c23_x;
    let d2 = rounded_f64(d2, 125)?;
    let mx_x_2 = d2 * c31_x;
    let mx_x_3 = mx_x_1 + mx_x_2;
    let d3 = rounded_f64(d3, 125)?;
    let mx_x_4 = d3 * c12_x;
    let mx_x = mx_x_3 + mx_x_4;
    let mx_y_1 = d1 * c23_y;
    let mx_y_2 = d2 * c31_y;
    let mx_y_3 = mx_y_1 + mx_y_2;
    let mx_y_4 = d3 * c12_y;
    let mx_y = mx_y_3 + mx_y_4;
    let mx_z_1 = d1 * c23_z;
    let mx_z_2 = d2 * c31_z;
    let mx_z_3 = mx_z_1 + mx_z_2;
    let mx_z_4 = d3 * c12_z;
    let mx_z = mx_z_3 + mx_z_4;
    let d4 = rounded_f64(d4, 125)?;
    let s_1 = d4 * w;
    let n4x = rounded_f64(n4x, 83)?;
    let s_2 = n4x * mx_x;
    let s_3 = s_1 - s_2;
    let n4y = rounded_f64(n4y, 83)?;
    let s_4 = n4y * mx_y;
    let s_5 = s_3 - s_4;
    let n4z = rounded_f64(n4z, 83)?;
    let s_6 = n4z * mx_z;
    let s = s_5 - s_6;
    let m_n1 = largest_magnitude([n1z, n1y, n1x]);
    let m_d1 = largest_magnitude([d1]);
    let m_n2 = largest_magnitude([n2y, n2z, n2x]);
    let m_d2 = largest_magnitude([d2]);
    let m_n3 = largest_magnitude([n3z, n3y, n3x]);
    let m_d3 = largest_magnitude([d3]);
    let m_n4 = largest_magnitude([n4x, n4y, n4z]);
    let m_d4 = largest_magnitude([d4]);
    let scale = larger(m_d1 * m_n2 * m_n3 * m_n4, m_n1 * m_d2 * m_n3 * m_n4);
    let scale = larger(scale, m_n1 * m_n2 * m_d3 * m_n4);
    let scale = larger(scale, m_n1 * m_n2 * m_n3 * m_d4);
    decide(s, ERROR, scale)
}

/// `tpi_side`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out; `None` also for a
/// rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::similar_names,
    clippy::too_many_arguments,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn value(
    n1x: i128,
    n1y: i128,
    n1z: i128,
    d1: i128,
    n2x: i128,
    n2y: i128,
    n2z: i128,
    d2: i128,
    n3x: i128,
    n3y: i128,
    n3z: i128,
    d3: i128,
    n4x: i128,
    n4y: i128,
    n4z: i128,
    d4: i128,
) -> Option<I384> {
    let n2y = within(n2y, 83)?;
    let n3z = within(n3z, 83)?;
    let c23_x_1 = I256::product_i128(n2y, n3z)?;
    let n2z = within(n2z, 83)?;
    let n3y = within(n3y, 83)?;
    let c23_x_2 = I256::product_i128(n2z, n3y)?;
    let c23_x = c23_x_1.checked_sub(&c23_x_2)?;
    let n3x = within(n3x, 83)?;
    let c23_y_1 = I256::product_i128(n2z, n3x)?;
    let n2x = within(n2x, 83)?;
    let c23_y_2 = I256::product_i128(n2x, n3z)?;
    let c23_y = c23_y_1.checked_sub(&c23_y_2)?;
    let c23_z_1 = I256::product_i128(n2x, n3y)?;
    let c23_z_2 = I256::product_i128(n2y, n3x)?;
    let c23_z = c23_z_1.checked_sub(&c23_z_2)?;
    let n1z = within(n1z, 83)?;
    let c31_x_1 = I256::product_i128(n3y, n1z)?;
    let n1y = within(n1y, 83)?;
    let c31_x_2 = I256::product_i128(n3z, n1y)?;
    let c31_x = c31_x_1.checked_sub(&c31_x_2)?;
    let n1x = within(n1x, 83)?;
    let c31_y_1 = I256::product_i128(n3z, n1x)?;
    let c31_y_2 = I256::product_i128(n3x, n1z)?;
    let c31_y = c31_y_1.checked_sub(&c31_y_2)?;
    let c31_z_1 = I256::product_i128(n3x, n1y)?;
    let c31_z_2 = I256::product_i128(n3y, n1x)?;
    let c31_z = c31_z_1.checked_sub(&c31_z_2)?;
    let c12_x_1 = I256::product_i128(n1y, n2z)?;
    let c12_x_2 = I256::product_i128(n1z, n2y)?;
    let c12_x = c12_x_1.checked_sub(&c12_x_2)?;
    let c12_y_1 = I256::product_i128(n1z, n2x)?;
    let c12_y_2 = I256::product_i128(n1x, n2z)?;
    let c12_y = c12_y_1.checked_sub(&c12_y_2)?;
    let c12_z_1 = I256::product_i128(n1x, n2y)?;
    let c12_z_2 = I256::product_i128(n1y, n2x)?;
    let c12_z = c12_z_1.checked_sub(&c12_z_2)?;
    let w_1 = c23_x.checked_mul_i128(n1x)?;
    let w_2 = c23_y.checked_mul_i128(n1y)?;
    let w_3 = w_1.checked_add(&w_2)?;
    let w_4 = c23_z.checked_mul_i128(n1z)?;
    let w = w_3.checked_add(&w_4)?;
    let d1 = within(d1, 125)?;
    let mx_x_1 = c23_x.resize::<5>()?.checked_mul_i128(d1)?;
    let d2 = within(d2, 125)?;
    let mx_x_2 = c31_x.resize::<5>()?.checked_mul_i128(d2)?;
    let mx_x_3 = mx_x_1.checked_add(&mx_x_2)?;
    let d3 = within(d3, 125)?;
    let mx_x_4 = c12_x.resize::<5>()?.checked_mul_i128(d3)?;
    let mx_x = mx_x_3.checked_add(&mx_x_4)?;
    let mx_y_1 = c23_y.resize::<5>()?.checked_mul_i128(d1)?;
    let mx_y_2 = c31_y.resize::<5>()?.checked_mul_i128(d2)?;
    let mx_y_3 = mx_y_1.checked_add(&mx_y_2)?;
    let mx_y_4 = c12_y.resize::<5>()?.checked_mul_i128(d3)?;
    let mx_y = mx_y_3.checked_add(&mx_y_4)?;
    let mx_z_1 = c23_z.resize::<5>()?.checked_mul_i128(d1)?;
    let mx_z_2 = c31_z.resize::<5>()?.checked_mul_i128(d2)?;
    let mx_z_3 = mx_z_1.checked_add(&mx_z_2)?;
    let mx_z_4 = c12_z.resize::<5>()?.checked_mul_i128(d3)?;
    let mx_z = mx_z_3.checked_add(&mx_z_4)?;
    let d4 = within(d4, 125)?;
    let s_1 = w.resize::<6>()?.checked_mul_i128(d4)?;
    let n4x = within(n4x, 83)?;
    let s_2 = mx_x.resize::<6>()?.checked_mul_i128(n4x)?;
    let s_3 = s_1.checked_sub(&s_2)?;
    let n4y = within(n4y, 83)?;
    let s_4 = mx_y.resize::<6>()?.checked_mul_i128(n4y)?;
    let s_5 = s_3.checked_sub(&s_4)?;
    let n4z = within(n4z, 83)?;
    let s_6 = mx_z.resize::<6>()?.checked_mul_i128(n4z)?;
    let s = s_5.checked_sub(&s_6)?;
    Some(s)
}

/// `tpi_side`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
#[allow(
    clippy::too_many_arguments,
    reason = "one parameter per input of the description"
)]
pub fn exact(
    n1x: i128,
    n1y: i128,
    n1z: i128,
    d1: i128,
    n2x: i128,
    n2y: i128,
    n2z: i128,
    d2: i128,
    n3x: i128,
    n3y: i128,
    n3z: i128,
    d3: i128,
    n4x: i128,
    n4y: i128,
    n4z: i128,
    d4: i128,
) -> Option<Sign> {
    value(
        n1x, n1y, n1z, d1, n2x, n2y, n2z, d2, n3x, n3y, n3z, d3, n4x, n4y, n4z, d4,
    )
    .map(|v| v.signum())
}
